import {furnitureCatalog,standardKind} from './furniture-catalog.js';
export const validId=v=>typeof v==='string'&&/^[a-f0-9-]{36}$/.test(v);
const finite=(v,a,b)=>Number.isFinite(v)&&v>=a&&v<=b;
export function validateObjects(items){if(!Array.isArray(items)||items.length>32)throw Error('房间最多保留 32 件新增作品');const seen=new Set();return items.map(o=>{if(!o||!validId(o.id)||!(o.standard?!!furnitureCatalog[o.standard]&&!o.asset:validId(o.asset))||seen.has(o.id)||typeof o.name!=='string'||!o.name.trim()||o.name.length>50||!['decor','seat','sofa','lamp','rug'].includes(o.kind)||![0,1].includes(o.floor)||!finite(o.x,-4.2,4.2)||!finite(o.z,o.mount&&o.mount!=='floor'?-3.5:-3,3)||!finite(o.yaw,-Math.PI,Math.PI)||!finite(o.width,.15,2.5)||!finite(o.height,['rug','tray','wallArt','clock'].includes(o.standard)?.025:.1,1.8)||!finite(o.depth,o.standard&&o.mount&&o.mount!=='floor'?.02:.15,1.3)||!finite(o.seat,.15,.9)||!/^#[a-fA-F0-9]{6}$/.test(o.tint)||o.description!==undefined&&(typeof o.description!=='string'||o.description.length>1024)||Object.keys(o).some(k=>!['id','asset','name','kind','floor','x','z','yaw','width','height','depth','seat','tint','description','standard','accent','shape','pattern','variant','mount','y','planter'].includes(k)))throw Error('家具参数不正确');if(o.standard&&(!/^#[a-fA-F0-9]{6}$/.test(o.accent)||!['round','square'].includes(o.shape)||!['plain','stripe','check'].includes(o.pattern)||o.kind!==standardKind(o.standard)||o.standard==='lamp'&&o.shape!=='round'||o.standard==='sofa'&&(o.seat>o.height-.18||o.seat<.35)||o.standard==='rug'&&o.height>.06))throw Error('家具样式不完整');if(!o.standard&&['mount','y','variant','planter'].some(k=>o[k]!==undefined))throw Error('外部家具不能使用支撑面参数');if(o.standard){const c=furnitureCatalog[o.standard];if(o.planter!==undefined&&(c.group!=='plant'||!['terracotta','ceramic'].includes(o.planter)))throw Error('花盆款式不正确');if(o.variant!==undefined&&!c.variants.includes(o.variant)||o.mount!==undefined&&!c.mounts.includes(o.mount)||o.y!==undefined&&(!finite(o.y,0,2.2)||!o.mount||o.mount==='floor'))throw Error('家具摆放或款式不正确');if(!['sofa','lamp','rug'].includes(o.standard)&&(!o.variant||!o.mount))throw Error('缺少家具款式或摆放方式');if(o.standard==='stool'&&(Math.abs(o.seat-o.height)>.03||o.height>.65))throw Error('座椅高度不正确');}seen.add(o.id);return {...o}})}
export function validateTailoring(v){if(v==null)return null;if(!v||!['skirt','dress','top','set','hat','veil'].includes(v.kind)||typeof v.name!=='string'||!v.name.trim()||v.name.length>50||!['plain','check','stripe','dots','flower'].includes(v.pattern)||!/^#[a-fA-F0-9]{6}$/.test(v.color)||!/^#[a-fA-F0-9]{6}$/.test(v.accent)||!finite(v.length,.18,.4)||!finite(v.flare,.02,.13)||!Number.isInteger(v.pleats)||v.pleats<0||v.pleats>24||!finite(v.patternScale,.03,.12)||Object.keys(v).some(k=>!['kind','name','pattern','color','accent','length','flare','pleats','patternScale','pantsColor'].includes(k)))throw Error('服饰结构不正确');if(v.pantsColor!==undefined&&!/^#[a-fA-F0-9]{6}$/.test(v.pantsColor)||v.kind==='set'&&!v.pantsColor)throw Error('裤子配色不完整');return {...v}}
